  if(text.startsWith("READ_MIB "))return (ar?"القراءة التسلسلية: ":"Sequential read: ")+text.substring(9)+" MiB/s";
  if(text.startsWith("COPIED "))return (ar?"الملفات المنسوخة: ":"Files copied: ")+text.substring(7);
