  if(text.startsWith("ZERO_VERIFIED ")){String[] parts=text.substring(14).split(" ",2);String time="";try{java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",java.util.Locale.ROOT);fmt.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));time=fmt.format(new java.util.Date(Long.parseLong(parts[1])));}catch(Exception ignored){}return (ar?"قُرئت كل البايتات القابلة للعنونة كأصفار: ":"All addressable bytes read back as zero: ")+parts[0]+"\n"+(ar?"وقت الجهاز (UTC): ":"Device time (UTC): ")+time+(ar?"\nهذا سجل تحقق محلي وليس شهادة محو معتمدة. لا يغطي خلايا الفلاش المخفية أو الاحتياطية أو يثبت السعة الحقيقية.":"\nThis is a local verification record, not certified sanitization. It does not cover hidden/spare flash cells or prove real capacity.");}
  if(text.startsWith("CHD_RAW_OK "))return (ar?"فُكت صورة CHDv5 الخام وتحقق الناتج: ":"CHDv5 raw image decoded and output verified: ")+text.substring(11)+(ar?"\nهذا لا يثبت توافق الإقلاع أو تشغيل الألعاب.":"\nThis does not prove boot or game compatibility.");
  if(text.startsWith("ARCHIVE_LIST\n")||text.startsWith("FSIMAGE_LIST\n")){String body=text.substring(13);String more="ARCHIVE_MORE ";int at=body.indexOf(more);if(at>=0)body=body.substring(0,at)+(ar?"مسارات إضافية لم تُعرض: ":"Additional paths not shown: ")+body.substring(at+more.length());return (text.startsWith("FSIMAGE")?(ar?"قائمة نظام الملفات (D مجلد، F ملف، S مسار غير مدعوم لا يُستخرج)\n":"Filesystem listing (D directory, F file, S unsupported path omitted from extraction)\n"):(ar?"قائمة الأرشيف بعد الفحص\n":"Validated archive listing\n"))+body;}
  if(text.startsWith("ARCHIVE_ALL_OK ")||text.startsWith("FSIMAGE_ALL_OK ")){String[] parts=text.substring(15).split("\n",3);return (ar?"استُخرجت الملفات وأعيدت قراءتها والتحقق ببصمة SHA-256: ":"Files extracted and SHA-256 readback verified: ")+parts[0]+"\n"+(ar?"إجمالي البايتات: ":"Total bytes: ")+(parts.length>1?parts[1]:"")+(text.startsWith("FSIMAGE")?"\n"+(ar?"مسارات أو أشجار غير مدعومة لم تُستخرج: ":"Unsupported paths/subtrees omitted: ")+(parts.length>2?parts[2]:"0"):"");}
  if(text.startsWith("ARCHIVE_EXTRACTED "))return (ar?"استُخرج الأرشيف. البايتات: ":"Archive extracted. Bytes: ")+text.substring(18);
