  if(text.startsWith("FS_CHECK_OK "))return (ar?"اكتمل فحص نظام الملفات للقراءة فقط: ":"Read-only filesystem check completed: ")+text.substring(12).toUpperCase(java.util.Locale.ROOT)+(ar?"\nلا يثبت الفحص السعة الحقيقية أو سلامة العتاد أو توافق الإقلاع.":"\nThis does not prove real capacity, hardware health or boot compatibility.");
  if(text.startsWith("FS_REPAIR_OK "))return (ar?"اكتمل الإصلاح المحدود وإعادة الفحص: ":"Limited repair and follow-up check completed: ")+text.substring(13).toUpperCase(java.util.Locale.ROOT)+(text.endsWith("ntfs")?(ar?"\nهذا إصلاح NTFS أساسي فقط. استخدم Windows chkdsk للفحص والإصلاح الكاملين.":"\nThis is basic NTFS repair only. Use Windows chkdsk for full checking/repair."):(ar?"\nتحقق من ملفاتك واحتفظ بالنسخة الاحتياطية؛ لا يضمن الإصلاح استعادة كل البيانات.":"\nCheck your files and keep backups; repair does not guarantee all data recovery."));
  if(text.startsWith("CONSOLE_SPLIT_OK\n")){String[] parts=text.split("\\n",4);return (ar?"اكتمل تقسيم الملف والتحقق من كل جزء. عدد الأجزاء: ":"File split and every part verified. Part count: ")+parts[1]+"\n"+(ar?"احتفظ بملف التحقق للدمج: ":"Keep this manifest for joining: ")+parts[2]+"\n"+(ar?"بصمة SHA-256 للملف الأصلي: ":"Original file SHA-256: ")+parts[3];}
  if(text.startsWith("CONSOLE_JOIN_OK\n")){String[] parts=text.split("\\n",3);return (ar?"اكتمل دمج الأجزاء والتحقق الكامل: ":"Parts joined and complete readback verified: ")+parts[1]+"\nSHA-256: "+parts[2];}
  if(text.startsWith("FAT_IMAGE_LIST "))return (ar?"قائمة صورة FAT: ":"FAT image listing: ")+text.substring(15);
