  if(text.equals("VENTOY_GPT_INSTALL_OK"))return ar?"اكتمل تثبيت Ventoy GPT والتحقق من بيانات الإقلاع وجداول الأقسام. اختبر الإقلاع على حاسوب.":"Ventoy GPT installation and boot-data/table verification completed. Test booting on a PC.";
  if(text.equals("VENTOY_GPT_UPDATE_OK"))return ar?"اكتمل تحديث Ventoy GPT والتحقق منه. حُفظت قطاعات البيانات والجداول. اختبر الإقلاع على حاسوب.":"Ventoy GPT update verified; data sectors and tables preserved. Test booting on a PC.";
  if(text.startsWith("CONTAINER_OK ")){String[] parts=text.substring(13).split("\\n",3);return (ar?"اكتمل التحويل والتحقق: ":"Conversion and verification completed: ")+parts[0]+"\n"+(ar?"بايتات البيانات الأصلية: ":"Original data bytes: ")+(parts.length>1?parts[1]:"")+"\n"+(ar?"بصمة SHA-256 للبيانات الأصلية: ":"SHA-256 of original data: ")+(parts.length>2?parts[2].replace("SHA-256: ",""):"");}
